class SaldoInsuficienteError(Exception):
    pass

def sacar(saldo, valor):
    if valor > saldo:
        raise SaldoInsuficienteError("Saldo insuficiente para este saque.")
    return round(saldo - valor, 2)

def mensagem_saldo_insuficiente(saldo, valor):
    try:
        return str(sacar(saldo, valor))
    except SaldoInsuficienteError as exc:
        return str(exc)

